{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.putaway_tracking AS SELECT a.\"Putaway Code\", CASE WHEN LOWER(a.\"Created By\") LIKE \'%store%\' THEN \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%return%\' and lower(a.type) like (\'%grn%\')THEN \'WPR Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%reverse%\' OR LOWER(a.type) LIKE \'%return%\' THEN \'B2C Return Inward\' WHEN LOWER(a.type) LIKE \'%cancelled%\' OR LOWER(a.type) LIKE \'%picklist%\' THEN \'Putback Activity\' WHEN LOWER(a.type) LIKE \'%shelf%\' THEN \'Audit Activity\' WHEN LOWER(a.type) LIKE \'%gatepass%\' THEN \'Gatepass Activity\' ELSE \'BAU_PT\' END AS final_type, a.type AS putaway_type, a.created::timestamp AS putaway_created, a.updated::timestamp AS putaway_updated, a.\"Inventory Type\", CAST(a.\"Total Quantity\" AS NUMERIC) AS total_quantity, CAST(a.\"Putaway Completed Quantity\" AS NUMERIC) AS putaway_completed_quantity, CAST(a.\"Total Quantity\" - a.\"Putaway Completed Quantity\" AS NUMERIC) AS pending_qty, a.\"Putaway Status Code\", upper(a.\"Putaway Item Status Code\") as \"Putaway Item Status Code\" , a.\"Bad inventory Reason\", a.\"Warehouse Name\", a.\"Putaway Item Id\", a.\"Item Type skuCode\", a.\"Putaway qc Comment\", a.\"Created By\", a.\"Shelf Code\", c.\"CATEGORY\" AS sku_category, c.sku_group, c.\"SKU_CLASS\" AS class, a.Category, a.EAN, a.NAME AS product_name, a.\"Batch Code\" FROM snitch_db.maplemonk.snitch_final_get_put_away_new AS a LEFT JOIN snitch_db.maplemonk.availability_master_v2 AS c ON upper(LEFT(a.\"Item Type skuCode\", LENGTH(a.\"Item Type skuCode\") - CHARINDEX(\'-\', REVERSE(a.\"Item Type skuCode\")))) = CASE WHEN POSITION(\'-\' IN c.sku_group) > 0 AND LEFT(c.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(c.sku_group, \'-\', 1)) WHEN POSITION(\'-\' IN c.sku_group) > 0 THEN UPPER(SPLIT_PART(c.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(c.sku_group, \'-\', 2)) ELSE UPPER(c.sku_group) END WHERE a.updated::date >= \'2024-04-01\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_floor_pendency1 AS ( SELECT \"WAREHOUSE\", status, CAST(SAPL_EMIZA AS INTEGER) AS EMIZA, CAST(\"SAPL-SR\" AS INTEGER) AS SR, CAST(\"SAPL-WH1\" AS INTEGER) AS WH1, CAST(\"SAPL-WH2\" AS INTEGER) AS WH2, CAST(store_returns AS INTEGER) AS STORE_RETURNS, ( COALESCE(CAST(emiza AS INTEGER), 0) + COALESCE(CAST(\"SR\" AS INTEGER), 0) + COALESCE(CAST(\"WH1\" AS INTEGER), 0) + COALESCE(CAST(\"WH2\" AS INTEGER), 0) + COALESCE(CAST(store_returns AS INTEGER), 0) ) AS total_final FROM SNITCH_DB.MAPLEMONK.GS_FLOOR_PENDENCY ); CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_summary_wh AS WITH rts AS ( SELECT TRY_TO_DATE(entry_date, \'DD/MM/YYYY\') AS date, sku AS style, description, repeat, new_style, CAST(REPLACE(online_qty, \',\', \'\') AS INT) as online_qty, vendor, rts_status, TRY_TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') AS expected_delivery_date, warehouse, class, ars, remark, photoshoot_received, qc_status, qc_report, costing, logic_po, pl_and_cm_receving_date, fabric_dc, work_order, mini_marker, invoice FROM snitch_db.maplemonk.gs_onlinegoods_rts ) SELECT rts.*, am.category, am.product_name, am.price, am.total_eoq, am.available_units, am.sku_class, am.sellable_inventory, am.status, md.final_status, case when logic_po is null or lower(photoshoot_received) not in (\'yes\') then \'Photoshoot-POpending\' else null end as RCA, case when md.final_status = \'INWARD_NOT_DONE\' then \'CATALOGUED\' when rts.style in (\'4MSR5199-01\',\'4MSR5199-02\',\'4MST2499-01\',\'4MST2499-02\',\'4MST2499-03\',\'4MST2500-01\',\'4MST2574-01\',\'4MST2574-02\',\'4MST2574-03\',\'4MST2574-04\',\'4MST2574-05\',\'4MST2574-06\',\'4MST2574-07\',\'4MST2574-08\',\'4MST2574-09\',\'4MST2574-10\',\'4MST2574-11\',\'4MST2574-12\',\'4MST2574-13\',\'4MST2574-14\',\'4MST2574-15\',\'4MST2574-16\',\'4MST2574-17\',\'4MST2574-18\',\'4MST2574-19\',\'4MST2571-01\',\'4MST2571-02\',\'4MST2571-03\',\'4MST2571-04\',\'4MST2571-05\',\'4MST2571-06\',\'4MST2516-01\',\'4MST2516-02\',\'4MST2516-03\',\'4MST2516-04\',\'4MSW9059-01\',\'4MSW9059-02\',\'4MSW9059-03\',\'4MSW9059-04\',\'4MSW9058-01\',\'4MSW9058-02\',\'4MSW9057-01\',\'4MSW9057-02\',\'4MST2518-01\',\'4MST2518-02\',\'4MST2518-03\',\'4MST2518-04\',\'4MST2517-01\',\'4MST2517-02\',\'4MST2517-03\',\'4MST2517-04\',\'4MSW9062-01\',\'4MSW9062-01\',\'4MSW9063-01\',\'4MSW9063-02\',\'4MSW9063-03\',\'4MSW9063-04\',\'4MSS3555-01\',\'4MSS3555-02\',\'4MSS3555-03\',\'4MSS3555-04\',\'4MSS3555-05\',\'4MSS3555-06\',\'4MSS3555-07\',\'4MST2500-02\',\'4MST2500-03\',\'4MST2500-04\',\'4MST2500-04\',\'4MST2500-06\',\'4MST2502-01\',\'4MST2502-02\',\'4MST2502-03\',\'4MST2502-04\',\'4MST2503-01\',\'4MST2503-02\',\'4MST2541-01\',\'4MST2541-02\',\'4MSW9052-01\',\'4MSW9052-02\',\'4MSW9052-03\',\'4MSW9052-04\',\'4MSW9055-01\',\'4MSW9055-02\',\'4MSW9055-03\',\'4MSWH9893-01\',\'4MSWH9893-02\',\'4MSWH9893-03\',\'4MSWH9893-04\',\'4MSWH9893-05\',\'4MSWH9893-06\',\'4MTP0042-01\',\'4MTP0042-02\',\'4MTP0042-03\',\'4MTP0042-04\',\'4MTP0043-01\',\'4MTP0043-02\',\'4MTP0043-03\',\'4MTP0043-04\',\'4MST2645-01\',\'4MST2645-02\',\'4MST2645-03\',\'4MST2645-04\',\'4MST2645-05\',\'4MST2645-06\',\'4MST2645-07\',\'4MST2645-08\',\'4MST2645-09\',\'4MST2644-01\',\'4MST2644-02\',\'4MST2644-03\',\'4MST2644-04\',\'4MST2644-05\',\'4MST2644-06\',\'4MST2644-07\',\'4MST2643-01\',\'4MST2643-02\',\'4MST2643-03\',\'4MST2643-04\',\'4MST2643-05\',\'4MST2643-06\',\'4MST2643-07\',\'4MST2643-08\',\'4MST2643-09\',\'4MST2643-10\',\'4MST2643-11\',\'4MST2643-12\',\'4MST2570-01\',\'4MST2570-02\',\'4MST2570-03\',\'4MST2570-04\',\'4MST2570-05\',\'4MCR1001-01\',\'4MCR1001-02\',\'4MCR1001-03\',\'4MCR1001-04\',\'4MCR1001-05\',\'4MCR1001-06\',\'4MCR1001-07\',\'4MCR1001-08\',\'4MCR1002-01\',\'4MCR1002-02\',\'4MCR1002-03\',\'4MCR1002-04\',\'4MCR1002-05\',\'4MCR1002-06\') then \'CORE\' when repeat = \'YES\' THEN \'REPEAT\' when lower(description) like \'%trouse%\' THEN \'BOTTOMS\' when lower(description) like \'%short%\' THEN \'BOTTOMS\' when lower(description) like \'%deni%\' THEN \'BOTTOMS\' when lower(description) like \'%py%\' THEN \'BOTTOMS\' when lower(description) like \'%jogg%\' THEN \'BOTTOMS\' when lower(description) like \'%chino%\' THEN \'BOTTOMS\' when lower(description) like \'%track%\' THEN \'BOTTOMS\' when lower(description) like \'%pant%\' THEN \'BOTTOMS\' when lower(description) like \'%cargo%\' THEN \'BOTTOMS\' when lower(description) in (\'trousers\',\'short\',\'boxer\',\'denim\',\'pyjama\',\'\') THEN \'BOTTOMS\' end as PRIORITY FROM rts LEFT JOIN snitch_db.maplemonk.availability_master_v2 am ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN am.sku_group) > 0 AND LEFT(am.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(am.sku_group, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN am.sku_group) > 0 THEN UPPER(SPLIT_PART(am.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(am.sku_group, \'-\', 2)) || \'%\' ELSE UPPER(am.sku_group) || \'%\' END LEFT JOIN snitch_db.maplemonk.sku_group_sample_to_live md ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN md.sku_group) > 0 AND LEFT(md.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN md.sku_group) > 0 THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(md.sku_group, \'-\', 2)) || \'%\' ELSE UPPER(md.sku_group) || \'%\' END where md.final_status not in (\'NO_ISSUES\',\'others\') ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            